-- Dansk portion 9 del 3/3: 166 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 6598-9992.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish9'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish9', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":6598,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå: 'Pigen, ___ jeg mødte i går, hedder Alma.'?","o":["der","hvis","som","hvad"],"a":"som","r":"Ledsætningen har allerede grundleddet 'jeg'. 'Der' kan kun bruges, når det selv er grundled i relativsætningen, så her skal det være 'som'."},
{"l":6618,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vikingerne efterlod kun få skriftlige kilder om sig selv. Meget af det, vi læser om deres togter, er skrevet af munke og andre, der blev udsat for dem.' Hvad bør man derfor huske, når man læser kilderne?","o":["At munke ikke kunne skrive særlig godt","At vikingerne slet ikke rejste så langt","At togterne slet ikke har fundet sted","At billedet af vikingerne kan være ensidigt"],"a":"At billedet af vikingerne kan være ensidigt","r":"Kilderne stammer fra ofrene, som havde grund til at beskrive vikingerne negativt. Man må derfor tænke over, hvem der fører ordet."},
{"l":6640,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Lærer A: Seks ugers sommerferie er for meget, for eleverne glemmer det lærte. Lærer B: Ferie er ikke tabt tid, for børn lærer også af at lege, rejse og kede sig.' Hvad er den grundlæggende forskel på de to syn?","o":["A tænker på skolestof, B ser læring mere bredt","A vil have mere ferie, B vil have mindre ferie","A taler om store børn, B taler om små børn","A bygger på forskning, B bygger på gæt"],"a":"A tænker på skolestof, B ser læring mere bredt","r":"Det, der skiller dem, er forståelsen af læring: A nævner det lærte stof, B regner også leg og rejser med."},
{"l":6662,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Kære dagbog. I dag sagde Oliver hej til mig. Han sagde også hej til læreren, pedellen og en hund, men det er ikke det, der er pointen.' Hvad viser sidste del af teksten?","o":["Skribenten synes, det er uhøfligt at hilse på en hund","Skribenten ved godt, at hilsenen ikke betød noget særligt","Skribenten er irriteret over, at Oliver kender pedellen","Skribenten hilser normalt også på alle mennesker selv"],"a":"Skribenten ved godt, at hilsenen ikke betød noget særligt","r":"Skribenten nævner selv de andre hilsner og bortforklarer dem så. Det er selvironi: Man ved det godt, men vil gerne håbe."},
{"l":6682,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'En ___ landede på hospitalets tag.'","o":["hellikopter","helikobter","helikopter","helikoptær"],"a":"helikopter","r":"Ordet kommer fra græsk 'helix' og 'pteron'. Det har ét l og pt midt i ordet."},
{"l":6700,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hun skrev til ham hver dag. / Postkassen var en mund, / der aldrig svarede.' Hvad udtrykker digtets billede?","o":["At posten kommer for sent","At brevene bliver for lange","At postkassen er ved at gå i stykker","At kontakten er helt ensidig"],"a":"At kontakten er helt ensidig","r":"En mund kan tale, men denne svarer aldrig. Hun rækker ud, og der kommer intet tilbage."},
{"l":6719,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Jeg har sagt det en million gange!' Hvilket virkemiddel er der her?","o":["overdrivelse","personifikation","allitteration","sammenligning"],"a":"overdrivelse","r":"Ingen har sagt det en million gange. Overdrivelsen, også kaldet hyperbel, viser, hvor træt personen er af at gentage sig."},
{"l":6740,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord har fået stort med urette: 'Vi lærer Spansk, når vi kommer til Valencia med Clara.'?","o":["Valencia","Spansk","Clara","Vi"],"a":"Spansk","r":"Sprog skrives med lille. Valencia og Clara er navne, og 'Vi' står først i sætningen."},
{"l":6761,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Fabrikken skal nedbringe sine emissioner.' Hvad skal den nedbringe?","o":["sine udgifter til strøm og vand","sit antal af ansatte i produktionen","sit udslip af stoffer til luften","sit salg af varer til udlandet"],"a":"sit udslip af stoffer til luften","r":"Emission betyder udsendelse. I miljøsammenhæng er det udslip af for eksempel CO2 eller andre stoffer."},
{"l":6783,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et nyhedskriterium hedder 'aktualitet'. Hvad kræver det af en historie?","o":["at den foregår tæt på der, hvor læserne bor","at den handler om kendte mennesker","at den indeholder en konflikt","at den handler om noget, der sker lige nu"],"a":"at den handler om noget, der sker lige nu","r":"Journalister vurderer nyheder efter kriterier. Aktualitet handler om tid: jo nyere begivenheden er, desto stærkere er historien."},
{"l":6800,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der stå komma: 'Det at du kom gjorde mig glad.'?","o":["kom","du","gjorde","mig"],"a":"kom","r":"Ledsætningen 'at du kom' står inde i sætningen og slutter efter 'kom'."},
{"l":6813,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Ministeren 'sendte en prøveballon op' om en ny regel. Hvad gjorde ministeren?","o":["vedtog reglen uden at spørge nogen","undersøgte, hvordan idéen ville blive modtaget","holdt en fest for at fejre reglen","trak reglen tilbage efter stor kritik"],"a":"undersøgte, hvordan idéen ville blive modtaget","r":"Man kan sende en lille ballon op for at se, hvordan vinden blæser. På samme måde kan man nævne en idé og se, hvordan folk reagerer."},
{"l":6836,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Direktøren fratræder til sommer.' Hvad sker der til sommer?","o":["direktøren begynder i sit job","direktøren får højere løn","direktøren forlader sit job","direktøren holder lang ferie"],"a":"direktøren forlader sit job","r":"'Fratræde' betyder at forlade en stilling. Det modsatte er 'tiltræde', som betyder at begynde i en stilling."},
{"l":6855,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Tapetet skallede af væggene. I køleskabet stod kun en halv liter mælk, og mor talte mønter ved køkkenbordet.' Hvad fortæller miljøet om familien?","o":["De er lige flyttet ind og skal male","De er ved at gøre klar til en stor fest","De er meget optagede af at spare på mælken","De har svært ved at få pengene til at slå til"],"a":"De har svært ved at få pengene til at slå til","r":"Detaljerne om det slidte hjem, det tomme køleskab og møntoptællingen viser, at familien mangler penge."},
{"l":6877,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Efter turen i det friske vejr havde alle en god ___.'","o":["appetit","apetit","apettit","appettit"],"a":"appetit","r":"Ordet har dobbelt-p og ét t i midten."},
{"l":6896,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Ida vil finde sin forsvundne kat. Naboens dreng tegner et kort over kvarteret til hende.' Hvad er objektet i aktantmodellen?","o":["Ida","Den forsvundne kat","Naboens dreng","Kortet over kvarteret"],"a":"Den forsvundne kat","r":"Objektet er det, subjektet stræber efter at nå. Ida er subjektet, og hun vil finde katten."},
{"l":6913,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Danmark underskriver en 'traktat'. Hvad er det?","o":["et budget for det næste år","en stor maskine til landbruget","en skriftlig aftale mellem lande","en rapport om et lands økonomi"],"a":"en skriftlig aftale mellem lande","r":"En traktat er en bindende aftale mellem stater. Ordet må ikke forveksles med 'traktor'."},
{"l":6936,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Firmaerne danner et 'kartel'. Hvad gør de?","o":["de slår sig sammen til ét nyt firma","de deler et kontor for at spare på huslejen","de sænker priserne for at vinde kunder","de aftaler priser i stedet for at konkurrere"],"a":"de aftaler priser i stedet for at konkurrere","r":"I et kartel aftaler firmaer priser eller markeder med hinanden. Det skader kunderne og er som regel forbudt."},
{"l":6958,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Hun sagde det ikke direkte, men kritikken lå ___ i hendes svar.'","o":["implicit","eksplicit","offentligt","konkret"],"a":"implicit","r":"Implicit betyder underforstået, altså at noget ligger i ordene uden at blive sagt direkte."},
{"l":6976,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"AIDA-modellen beskriver, hvordan en reklame virker. Hvad skal reklamen til sidst få modtageren til?","o":["At opdage reklamen","At handle og købe varen","At blive interesseret","At få lyst til varen"],"a":"At handle og købe varen","r":"AIDA står for attention, interest, desire og action. Det sidste trin er handlingen, altså købet."},
{"l":6996,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Spillerens kontrakt indeholder en 'klausul'. Hvad er det?","o":["en underskrift fra en advokat","en oversigt over tidligere klubber","en særlig bestemmelse i aftalen","en rabat på billetter til kampene"],"a":"en særlig bestemmelse i aftalen","r":"En klausul er en bestemt regel i en kontrakt, for eksempel om hvad der sker, hvis spilleren skifter klub."},
{"l":7014,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord indleder en spørgende ledsætning: 'Hun spurgte, ___ toget kørte.'?","o":["at","som","der","hvornår"],"a":"hvornår","r":"Efter 'spurgte' følger et indirekte spørgsmål, og det indledes her med hv-ordet 'hvornår'."},
{"l":7033,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Når bussen bremser, ryger passagererne fremad på grund af 'inerti'. Hvad er det?","o":["kroppens modstand mod at ændre bevægelse","bremsernes kraft på alle bussens hjul","luftens modstand mod bussens forende","vejens hældning ned ad bakke"],"a":"kroppens modstand mod at ændre bevægelse","r":"Inerti, eller træghed, betyder, at noget i bevægelse vil fortsætte med samme fart og i samme retning, til en kraft ændrer det."},
{"l":7058,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"'Ali malede bænken' bliver til 'Bænken blev malet af Ali.' Hvad sker der med det oprindelige grundled?","o":["Det bliver til sætningens verbum.","Det rykker ned i et led med 'af'.","Det bliver til et hensynsled.","Det bliver stående som grundled."],"a":"Det rykker ned i et led med 'af'.","r":"I passiv overtager genstandsleddet pladsen som grundled, og den, der handler, nævnes med 'af' eller slet ikke."},
{"l":7078,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Skolen indfører 'drakoniske' regler. Hvordan er reglerne?","o":["meget uklare","meget gamle","meget strenge","meget lempelige"],"a":"meget strenge","r":"Ordet kommer af Drakon, som i det gamle Athen skrev byens love ned med meget hårde straffe. Det har altså intet med drager at gøre."},
{"l":7100,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad viser anførselstegnene i: 'Hans »hjælp« gjorde kun tingene værre.'?","o":["At ordet står i flertal","At ordet er forkortet","At ordet er et stednavn","At ordet er ment ironisk"],"a":"At ordet er ment ironisk","r":"Anførselstegn kan vise, at skribenten ikke mener ordet helt bogstaveligt. Hjælpen var jo ingen hjælp."},
{"l":7120,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"I H.C. Andersens 'Grantræet' længes træet hele tiden efter det næste og glæder sig aldrig over det, det har. Hvilket tema passer bedst?","o":["At man glemmer at nyde nuet","Hævn efter en stor uret","Kærlighed mellem to søskende","Kampen om penge og magt"],"a":"At man glemmer at nyde nuet","r":"Først til sidst forstår træet, at det gode var der hele tiden. Eventyret handler om at leve i nuet."},
{"l":7146,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er det egentlige grundled i: 'Der sidder en kat på taget.'?","o":["Der","en kat","sidder","på taget"],"a":"en kat","r":"'Der' er et formelt grundled, som holder pladsen. Det er katten, sætningen handler om, så 'en kat' er det egentlige grundled."},
{"l":7167,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En forsker skriver en længere, holdningspræget artikel i en avis. Hvad kaldes den slags tekst?","o":["en notits","en nekrolog","en kronik","en annonce"],"a":"en kronik","r":"En kronik er en længere meningstekst, ofte skrevet af en fagperson uden for avisen. En notits er derimod en meget kort nyhed."},
{"l":7188,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken digter har skrevet 'Guldhornene'?","o":["Steen Steensen Blicher","Herman Bang","Ludvig Holberg","Adam Oehlenschläger"],"a":"Adam Oehlenschläger","r":"Adam Oehlenschläger skrev digtet, efter at de berømte guldhorn var blevet stjålet."},
{"l":7203,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Overskrift i Avis A: Over 90 procent af eleverne møder hver dag. Overskrift i Avis B: Hver tolvte elev mangler i skolen. Begge bygger på samme undersøgelse.' Hvad kan man slutte om de to aviser?","o":["De vinkler de samme tal forskelligt","De bygger på hver sin slags tal","Den ene avis må have regnet forkert","De er uenige om, hvad fravær betyder"],"a":"De vinkler de samme tal forskelligt","r":"Hver tolvte er cirka otte procent, så tallene passer sammen. A fremhæver det gode, B det dårlige: det er vinkling."},
{"l":7225,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Min ___ har bygget en ny idrætshal ved skolen.'","o":["komune","kommune","kummune","kommunne"],"a":"kommune","r":"Ordet har dobbelt-m, ét n og o i første stavelse."},
{"l":7244,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket værk er skrevet af Herman Bang?","o":["Niels Lyhne","Hosekræmmeren","Ved Vejen","Pelle Erobreren"],"a":"Ved Vejen","r":"'Ved Vejen' fra 1886 er en af Herman Bangs mest kendte fortællinger om et stille liv ved en lille station."},
{"l":7267,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige form: 'Efter de mange beskeder var jeg helt ___.'","o":["forvirred","forviret","forvirrt","forvirret"],"a":"forvirret","r":"Ordet har dobbelt-r, og tillægsformen ender på -et, selvom det lyder som d."},
{"l":7287,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'fordum' i sætningen 'Fordum stod her en stor skov'?","o":["for længe siden","i dette øjeblik","om kort tid","hvert eneste år"],"a":"for længe siden","r":"'Fordum' er et gammelt ord for 'i gamle dage'. Det møder man især i eventyr og ældre tekster."},
{"l":7304,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken form er rigtig: '___ hovedstad hedder Washington.'?","o":["USA:s","USA's","U.S.A.'s","USA-s"],"a":"USA's","r":"USA skrives uden punktummer, og genitiv-s kan skilles fra forkortelsen med apostrof. Kolon og bindestreg bruges ikke her."},
{"l":7326,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Du kan tage bussen eller jeg kan køre dig.'?","o":["tage","jeg","bussen","køre"],"a":"bussen","r":"Der er to hovedsætninger med hvert sit grundled, så kommaet skal stå foran 'eller'."},
{"l":7347,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør en person, der 'manipulerer' med sine venner?","o":["hjælper dem med deres opgaver hver eneste dag","fortæller dem sandheden uanset følgerne","inviterer dem med på en lang ferie","styrer dem i det skjulte for at få sin vilje"],"a":"styrer dem i det skjulte for at få sin vilje","r":"At manipulere er at påvirke andre uden at de opdager det. Ordet er negativt, fordi man bruger andre til sine egne formål."},
{"l":7370,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at noget er 'betænkeligt'?","o":["at det vækker bekymring","at det er fint gennemtænkt","at det viser omsorg for andre","at det er svært at huske"],"a":"at det vækker bekymring","r":"Noget betænkeligt får en til at tøve, fordi det kan gå galt. Ordet 'betænksom' er noget andet: det betyder, at man tænker på andre."},
{"l":7388,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om naboerne har en gensidig s-form?","o":["Hækken klippes af naboen.","De to naboer skændes tit.","Haven passes om sommeren.","Huset sælges til foråret."],"a":"De to naboer skændes tit.","r":"'Skændes' betyder, at de skælder ud på hinanden, så handlingen går begge veje. De andre s-former er passive."},
{"l":7400,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Undersøgelsen konkluderer, at 80 procent af danskerne dyrker motion flere gange om ugen. Spørgeskemaerne blev delt ud i kommunens idrætshaller.' Hvad er problemet med konklusionen?","o":["Procenttallet er for højt til at kunne være rigtigt","Spørgeskemaer kan slet ikke bruges til at måle motion","De adspurgte er ikke repræsentative for alle danskere","Idrætshaller er ikke åbne flere gange om ugen"],"a":"De adspurgte er ikke repræsentative for alle danskere","r":"Folk i idrætshaller dyrker naturligvis oftere motion. Man kan ikke overføre deres svar til hele befolkningen."},
{"l":7421,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord kan erstatte slangordet i en formel tekst: 'Det var virkelig nederen, at kampen blev aflyst.'?","o":["heldigt","fedt","skønt","ærgerligt"],"a":"ærgerligt","r":"'Nederen' er slang for noget, der er ærgerligt eller trist. 'Fedt' og 'skønt' betyder næsten det modsatte."},
{"l":7443,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er 'der' i: 'Vi var der hele sommeren.'?","o":["et biord for sted","et formelt grundled","et henførende ord","et spørgende stedord"],"a":"et biord for sted","r":"Her svarer 'der' på spørgsmålet 'hvor?'. Grundleddet er 'vi', så 'der' kan ikke være formelt grundled."},
{"l":7463,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad mangler? 'Tandlægens ___ gjorde instrumenterne klar.'","o":["asistent","assistent","assistænt","assistant"],"a":"assistent","r":"Ordet har dobbelt-s i starten. På dansk ender det på -ent, ikke -ant som på engelsk."},
{"l":7487,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kalder man leddet 'min lillebror' i: 'Emil, min lillebror, går i 2. klasse.'?","o":["prædikativ","adverbial","apposition","verballed"],"a":"apposition","r":"En apposition står lige efter et ord og siger det samme på en anden måde. Den står mellem kommaer."},
{"l":7500,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Selv min lillebror kunne finde ud af det nye system.' Hvad antyder ordet 'selv' om lillebroren?","o":["At han har fundet ud af det helt uden hjælp","At han er den første, der fandt ud af systemet","At han er den eneste, der bruger det nye system","At man ikke forventer meget af ham på dette område"],"a":"At man ikke forventer meget af ham på dette område","r":"Et lille ord lægger en forventning ind: Hvis han kan, kan alle. Ordet 'selv' her betyder ikke 'uden hjælp' men 'endda'."},
{"l":7520,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er hovedsætningens verbum: 'Da klokken ringede, løb alle ud på legepladsen.'?","o":["løb","ringede","alle","ud"],"a":"løb","r":"'Ringede' hører til ledsætningen 'Da klokken ringede'. I hovedsætningen står 'løb' lige efter ledsætningen, og grundleddet 'alle' følger bagefter."},
{"l":7542,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad angiver ledsætningen i: 'Vi cykler, medmindre det sner.'?","o":["indrømmelse","betingelse","sammenligning","formål"],"a":"betingelse","r":"'Medmindre' betyder 'hvis ikke'. Vi cykler altså på den betingelse, at det ikke sner."},
{"l":7558,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I sætningen 'Skolen bør starte senere, fordi unge sover for lidt' er der både en påstand og noget, der støtter den. Hvad kaldes støtten?","o":["hjemmel","gendrivelse","belæg","modifikation"],"a":"belæg","r":"Belægget er den begrundelse, man giver for sin påstand. Her er det 'unge sover for lidt', som skal støtte påstanden om senere skolestart."},
{"l":7586,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er N.F.S. Grundtvig især kendt for i dansk kulturhistorie?","o":["Noveller om livet på den jyske hede","Komedier for teatret i Lille Grønnegade","Forelæsninger om det moderne gennembrud","Salmer og tanken om folkehøjskolen"],"a":"Salmer og tanken om folkehøjskolen","r":"Grundtvig skrev et stort antal salmer, og hans tanker om folkelig oplysning førte til folkehøjskolerne."},
{"l":7603,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hun afviste 'kategorisk' forslaget. Hvordan afviste hun det?","o":["fuldstændigt og uden forbehold","høfligt og uden at hæve stemmen","kun for en kort tid fremover","med et lille smil på læben"],"a":"fuldstændigt og uden forbehold","r":"Den, der siger noget kategorisk, lader ikke plads til tvivl eller undtagelser. Ordet bruges tit om et klart og endegyldigt nej."},
{"l":7625,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Klokken var halv tolv, da Emilie hørte nøglen i døren. Hun slukkede lyset og trak dynen op. Da mor åbnede døren en sprække, trak hun vejret langsomt, som man gør, når man sover.' Hvad er der sket?","o":["Emilie er faldet i søvn med lyset slukket","Emilie lader, som om hun sover","Mor er vågnet af lyden af Emilies vejrtrækning","Emilie har låst døren, så mor ikke kan komme ind"],"a":"Emilie lader, som om hun sover","r":"Sammenligningen 'som man gør, når man sover' afslører, at hun gør det med vilje. Hun er vågen og spiller søvn."},
{"l":7642,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'asfalt / mit ansigt i ruden / nogen / et tog der ikke kommer' Hvilken periode minder digtet mest om?","o":["romantikken","oplysningstiden","modernismen","det moderne gennembrud"],"a":"modernismen","r":"Brudstykker, frie vers, storbyen og en følelse af tomhed er typiske træk ved modernismen."},
{"l":7663,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord beskriver en gruppe, hvor medlemmerne er meget forskellige?","o":["homogen","hermetisk","harmonisk","heterogen"],"a":"heterogen","r":"'Hetero' betyder anderledes, og 'homo' betyder ens. En heterogen gruppe er sammensat af vidt forskellige medlemmer, mens en homogen gruppe er ensartet."},
{"l":7686,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvem er en 'mø' i en gammel folkevise?","o":["en ung ugift kvinde","en gammel klog kone","en fattig omrejsende tigger","en lille dreng fra gården"],"a":"en ung ugift kvinde","r":"'Mø' er et gammelt ord for en ung, ugift kvinde. Det lever videre i det lidt ældre ord 'ungmø'."},
{"l":7705,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Du kommer ind i rummet, og alle kigger op. Du lader, som om du leder efter nogen. Du finder en plads ved vinduet og tager telefonen frem, selv om den er død.' Hvorfor er teksten sandsynligvis skrevet i du-form?","o":["Fortælleren irettesætter en bestemt person","Læseren bliver sat i personens sted","Forfatteren skriver et brev til sin ven","Teksten er en instruktion om mødeskik"],"a":"Læseren bliver sat i personens sted","r":"Du-formen trækker læseren ind, så man mærker ubehaget ved at være den, alle kigger på."},
{"l":7724,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige, at en artikel er 'tendentiøs'?","o":["den er skrevet med mange tal og nøjagtige fakta","den er skrevet i en let og meget morsom tone","den er skrevet for at fremme ét bestemt synspunkt","den er skrevet som et svar på en læsers brev"],"a":"den er skrevet for at fremme ét bestemt synspunkt","r":"Tendentiøs betyder, at noget er ensidigt og vil føre læseren i en bestemt retning. Ordet er beslægtet med 'tendens', men det er negativt ladet."},
{"l":7746,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Skolen bør servere gratis frugt, for eleverne lærer bedre, når de ikke er sultne.' Hvilken sætning er hjemlen?","o":["Skolen bør servere gratis frugt","Eleverne lærer bedre uden sult","Frugt er sundere end en kage fra bageren på hjørnet","Skolen bør gøre det, der hjælper elever med at lære"],"a":"Skolen bør gøre det, der hjælper elever med at lære","r":"Hjemlen er den underforståede antagelse, der forbinder belæg og påstand. Først når man er enig i den, holder argumentet."},
{"l":7766,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig om faren til en af dine venner?","o":["Det er en af mine venners far.","Det er en af mine venner's far.","Det er en af mine venners' far.","Det er en af mine vennerss far."],"a":"Det er en af mine venners far.","r":"Genitiv får bare et s. Det gælder også ord i flertal, så der skal ikke apostrof."},
{"l":7785,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Der var ikke ___ plads til alle i bussen.'","o":["tilstrækelig","tilstrækkelig","tillstrækkelig","tilstrækkeli"],"a":"tilstrækkelig","r":"Ordet kommer af 'strække' og har dobbelt-k. Forstavelsen 'til-' har ét l."},
{"l":7802,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes det, når en debattør selv nævner et modargument og derefter afviser det?","o":["hjemmel","belæg","gendrivelse","anslag"],"a":"gendrivelse","r":"Ved at møde modargumentet og tage luften ud af det styrker debattøren sin egen sag."},
{"l":7822,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvornår er en spørgeskemaundersøgelse 'repræsentativ'?","o":["når den er foretaget af en offentlig myndighed","når den stiller mange forskellige spørgsmål","når den bliver gentaget flere gange om året","når de adspurgte ligner befolkningen som helhed"],"a":"når de adspurgte ligner befolkningen som helhed","r":"En repræsentativ undersøgelse har svarpersoner, der tilsammen afspejler hele den gruppe, man udtaler sig om. Ellers kan man ikke generalisere ud fra den."},
{"l":7841,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'På opslagstavlen står der: Alle elever må ikke bruge mobil i timen.' Hvorfor er sætningen tvetydig?","o":["Det kan betyde, at ingen må, eller at kun nogle må","Det kan betyde, at det gælder timen eller frikvarteret","Det kan betyde, at det gælder mobilen eller computeren","Det kan betyde, at elever eller lærere har skrevet det"],"a":"Det kan betyde, at ingen må, eller at kun nogle må","r":"'Alle … ikke' kan læses som 'ingen' eller som 'ikke alle'. Sætningens orden gør det uklart, hvor nægtelsen hører til."},
{"l":7861,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Det var et ___ barn, der gik hjem fra festen.'?","o":["tilfredst","tilfreds","tilfredse","tilfredsen"],"a":"tilfreds","r":"Tillægsordet 'tilfreds' ender på -s og får ikke -t i intetkøn. Derfor hedder det 'et tilfreds barn'."},
{"l":7883,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Det var et ___ valg for hele klassen.'?","o":["lett","lette","let","letter"],"a":"let","r":"'Let' ender allerede på -t, så intetkønsformen ser ens ud. 'Lette' er flertal eller bestemt form."},
{"l":7905,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvorfor står der -t på 'hurtigt' i: 'Bussen kører hurtigt.'?","o":["Ordet 'bussen' er et intetkønsord.","Sætningen står i passiv datid.","Bussen er her i flertal.","Ordet beskriver verbet 'kører'."],"a":"Ordet beskriver verbet 'kører'.","r":"Her bruges tillægsordet som biord, fordi det beskriver verbet. Så får det -t. Det har intet med køn at gøre, for det hedder 'en bus'."},
{"l":7927,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad lavede en 'degn' i de gamle landsbyer?","o":["hjalp præsten og underviste børn","bagte brød til hele byen","smedede redskaber til bønderne","passede byens fælles kvæg"],"a":"hjalp præsten og underviste børn","r":"Degnen var præstens medhjælper ved kirken og var ofte også landsbyens lærer. Han er kendt fra både romaner og fortællinger om livet på landet."},
{"l":7944,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jeg har arbejdet som idrætsfysioterapeut i 20 år. I den tid har jeg undersøgt tusindvis af fødder. Derfor løber jeg selv kun med Trinfast-såler i skoene.' Hvilken appelform bruger reklamen især?","o":["Logos, fordi tallene beviser, at sålerne virker","Etos, fordi afsenderens faglighed skal skabe tillid","Patos, fordi læseren skal blive bekymret for sine fødder","Logos, fordi produktet sammenlignes med andre såler"],"a":"Etos, fordi afsenderens faglighed skal skabe tillid","r":"Reklamen bygger på, at vi stoler på en fagperson. Tallene ligner logos, men de siger noget om afsenderens erfaring og beviser intet om sålerne."},
{"l":7967,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg det rigtige ord: 'Alle elever får en ___ samtale med læreren.'","o":["indeviduel","individuell","individuel","individual"],"a":"individuel","r":"Ordet skrives med i i alle stavelser foran -uel, og det slutter med ét l."},
{"l":7987,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I H.C. Andersens 'Det er ganske vist!' bliver en fjer til fem høns. Hvad viser historien?","o":["at en høne altid vil beskytte sine kyllinger i hønsehuset","at et lille dyr kan klare sig bedre end et stort dyr","at et ærligt menneske altid får belønning til sidst","at en lille historie vokser, når den bliver fortalt videre"],"a":"at en lille historie vokser, når den bliver fortalt videre","r":"Historien bliver større, hver gang den går videre. Derfor siger vi stadig, at nogen 'gør en fjer til fem høns'."},
{"l":8004,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Det var ikke helt dårligt, sagde Asta, da hun havde vundet en halv million.' Hvilket virkemiddel bruger Asta?","o":["underdrivelse","hyperbel","oxymoron","lydord"],"a":"underdrivelse","r":"Asta siger meget mindre, end hun mener. Underdrivelsen virker morsom, fordi gevinsten er så stor."},
{"l":8025,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør en forfatter, der 'problematiserer' et emne i et essay?","o":["fortæller sjove historier, som skal gøre emnet lettere","peger på det, der er uafklaret eller svært ved emnet","skriver om, hvordan problemet allerede er blevet løst","gør emnet kortere, så læserne ikke skal læse så meget"],"a":"peger på det, der er uafklaret eller svært ved emnet","r":"At problematisere er at stille spørgsmål ved noget, som ser ud til at være selvfølgeligt. Det er en vigtig arbejdsmåde i både essays og opgaver."},
{"l":8047,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hver morgen klokken seks stod Ellen op og smurte to stykker mad. Hun pakkede dem i papir og lagde dem på køkkenbordet. Fabrikken havde været lukket i et år.' Hvad viser den sidste sætning?","o":["At hun har fået et nyt job, der begynder senere","At hun har glemt at spise sin morgenmad i et år","At hun holder fast i et arbejdsliv, der er forbi","At fabrikken snart åbner igen om morgenen"],"a":"At hun holder fast i et arbejdsliv, der er forbi","r":"Madpakken har ikke længere noget formål, men vanen består. Den tørre sidste sætning vender hele billedet."},
{"l":8069,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Om samme hændelse skriver skolebladet: Elever samledes roligt foran kontoret for at fremføre deres ønsker. Skolens nyhedsbrev skriver: En gruppe råbende elever blokerede indgangen til kontoret.' Hvad viser de to tekster?","o":["Der må have været tale om to forskellige hændelser","Skolebladet og nyhedsbrevet er enige om elevernes opførsel","Nyhedsbrevet giver det mest neutrale billede af hændelsen","Ordvalg farver, hvordan samme hændelse opfattes"],"a":"Ordvalg farver, hvordan samme hændelse opfattes","r":"'Samledes roligt' og 'råbende … blokerede' giver to billeder af det samme. Læseren kan ikke uden mere viden sige, hvad der er rigtigt."},
{"l":8092,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er grundleddet i: 'Prisen blev givet til Nanna af borgmesteren.'?","o":["Prisen","Nanna","borgmesteren","blev givet"],"a":"Prisen","r":"I passiv er grundleddet ikke den, der handler. Spørg: Hvad blev givet? Det gjorde prisen."},
{"l":8107,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Feber er et typisk ___ på influenza.'","o":["symtom","symptom","sympton","simptom"],"a":"symptom","r":"Husk p'et efter m, selvom det næsten ikke høres. Ordet skrives med y og ender på m."},
{"l":8126,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Telefonen ringede. Hun så på navnet på skærmen, og hendes skuldre blev stive. Så lagde hun den i lommen og gik videre, mens den blev ved.' Hvad gør forfatteren for at skabe spænding?","o":["Fortæller åbent, hvem der ringer, og hvad vedkommende vil","Beskriver telefonens udseende i mange detaljer","Holder navnet skjult og viser kun hendes reaktion","Lader fortælleren forklare, hvad hun føler"],"a":"Holder navnet skjult og viser kun hendes reaktion","r":"Læseren ser reaktionen, men ikke årsagen. Det, der holdes tilbage, skaber nysgerrighed."},
{"l":8149,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Tryllekunstneren skabte en ___ af, at kvinden svævede.'","o":["ilusion","illussion","illution","illusion"],"a":"illusion","r":"Ordet har dobbelt-l og ét s."},
{"l":8172,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hele byen kaldte hende Den Gule. Ingen vidste hvorfor, men alle lukkede deres vinduer, når hun gik forbi. Jeg var ti, før jeg turde kigge på hendes ansigt, og det var bare et ansigt.' Hvad vil uddraget fortælle?","o":["At frygten hviler på rygter og ikke på noget virkeligt","At kvinden i virkeligheden har gjort byen stor skade","At fortælleren selv er blevet kaldt Den Gule i byen","At byens beboere er meget optagede af farven gul"],"a":"At frygten hviler på rygter og ikke på noget virkeligt","r":"Ingen kender årsagen, og 'bare et ansigt' afmonterer frygten. Teksten viser, hvordan fordomme bliver gentaget uden grund."},
{"l":8191,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Ida sagde: 'Jeg er træt.' Hvilken sætning gengiver det som indirekte tale?","o":["Ida sagde, at jeg var træt.","Ida sagde, at hun var træt.","Ida spurgte, om hun var træt.","Ida sagde, at træt var jeg."],"a":"Ida sagde, at hun var træt.","r":"I indirekte tale bliver 'jeg' til 'hun', fordi det nu er en anden, der fortæller. Replikken bliver til en at-sætning."},
{"l":8213,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I en gammel roman beskrives en kvinde som 'ærbar'. Hvordan er hun?","o":["rig og mægtig","syg og svækket","anstændig og sømmelig","vred og hævngerrig"],"a":"anstændig og sømmelig","r":"'Ærbar' er et ældre ord for en person, der opfører sig sømmeligt og er værd at agte. Det hænger sammen med ordet 'ære'."},
{"l":8235,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'det forjættede land' i ældre tekster?","o":["det land, der er ramt af en forbandelse","det land, der ligger længst mod nord","det land, der blev erobret af kæmper","det land, der er lovet nogen"],"a":"det land, der er lovet nogen","r":"'Forjætte' er et gammelt ord for 'love'. Udtrykket kommer fra Bibelen, men bruges i dag også om et sted, man drømmer om."},
{"l":8256,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad handler Herman Bangs fortælling 'Ved Vejen' om?","o":["En stille kones uforløste længsel ved en lille station","En ung ingeniørs store planer om at ændre Danmark","En fattig dreng, der kæmper sig op på Bornholm","En klog pige, der vokser op i Københavns baggårde"],"a":"En stille kones uforløste længsel ved en lille station","r":"Fortællingen handler om Katinka Bai, som lever et stille liv ved en lille jernbanestation, og om alt det, der aldrig bliver sagt."},
{"l":8275,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Det er svært at ___ et nederlag.'","o":["acseptere","acceptere","akceptere","accebtere"],"a":"acceptere","r":"Ordet har dobbelt-c, som i 'accept', og står i navneform efter 'at'."},
{"l":8301,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led er at-sætningen i: 'Det glæder mig, at du kommer.'?","o":["genstandsled","hensynsled","egentligt grundled","forholdsordsled"],"a":"egentligt grundled","r":"Spørg: Hvad glæder mig? Svaret er at-sætningen. 'Det' er formelt grundled, og 'mig' er genstandsled."},
{"l":8318,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Orkestret spiller falsk, og der er larm fra vejen. Hvilket ord dækker denne lyd?","o":["symfoni","polyfoni","megafon","kakofoni"],"a":"kakofoni","r":"'Kako' betyder dårlig, og 'foni' betyder lyd. En kakofoni er en ubehagelig blanding af skurrende lyde."},
{"l":8343,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Bier dør ikke kun af sprøjtemidler. Mangel på blomster, sygdomme og vejret spiller også ind. Det gør det svært at pege på én skyldig.' Hvad er det centrale budskab?","o":["Biernes problemer har flere årsager, som hænger sammen","Sprøjtemidler er helt uden betydning for bierne","Vejret er den vigtigste grund til, at bier dør","Mangel på blomster er værre end sygdomme for bier"],"a":"Biernes problemer har flere årsager, som hænger sammen","r":"Teksten siger 'ikke kun', altså også sprøjtemidler. Pointen er, at sagen er kompleks, og at én enkelt forklaring ikke er nok."},
{"l":8363,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En historiker skriver om, hvad der ville være sket, hvis Danmark havde vundet krigen i 1864. Hvad kaldes den tankegang?","o":["autentisk","kontrafaktisk","dokumentarisk","kronologisk"],"a":"kontrafaktisk","r":"Kontrafaktisk betyder 'imod fakta'. Man leger med en tænkt historie for at forstå, hvad der gjorde den virkelige udvikling mulig."},
{"l":8387,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad kalder man reglerne for, hvordan ord skal staves? Vælg det rigtige ord.","o":["retsskrivning","rædskrivning","retskrivning","retskrivnin"],"a":"retskrivning","r":"Ordet består af 'ret' og 'skrivning'. Der er ét s, for der er intet fuge-s her."},
{"l":8408,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad handler et 'eksistentielt' spørgsmål om?","o":["praktiske forhold i hverdagen","økonomi og forbrug i samfundet","den nyeste forskning i naturfag","livets grundlæggende vilkår og mening"],"a":"livets grundlæggende vilkår og mening","r":"Et eksistentielt spørgsmål kunne være: 'Hvorfor er jeg her?' Sådanne spørgsmål er et vigtigt tema i litteraturen."},
{"l":8430,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'prekær' situation?","o":["en usikker og vanskelig situation","en festlig og munter situation","en daglig og velkendt situation","en kort og hurtigt overstået situation"],"a":"en usikker og vanskelig situation","r":"Prekær betyder usikker og faretruende. Lad dig ikke forvirre af lyden: Ordet har intet med 'præcis' at gøre."},
{"l":8448,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning indeholder en fejl i et tal?","o":["Der kom 3.500 tilskuere.","Løbet er 2.5 km langt.","Turen kostede 89,50 kr.","Vi mødes kl. 16.45."],"a":"Løbet er 2.5 km langt.","r":"Decimaltal skal skrives med komma på dansk: 2,5 km."},
{"l":8471,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Selvom alle prøvede at stoppe det, var en konflikt nu ___.'","o":["uungåelig","unngåelig","uundgåelig","uundgåli"],"a":"uundgåelig","r":"Ordet består af 'u-' og 'undgåelig', så der er to u'er i starten, og d'et skal med."},
{"l":8491,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Restauranten har fået ny kok. Portionerne er blevet små, priserne store, og tallerkenerne ligner kunstudstillinger. Det er vist det, der kaldes gastronomi.' Hvilken holdning har anmelderen til forandringen?","o":["Anmelderen er imponeret og anbefaler stedet varmt","Anmelderen er neutral og oplyser blot om priserne","Anmelderen er trist over, at kokken er rejst","Anmelderen er spottende og finder det overdrevet"],"a":"Anmelderen er spottende og finder det overdrevet","r":"'Det er vist det, der kaldes' tager afstand fra ordet gastronomi. Tonen er ironisk, ikke beundrende."},
{"l":8514,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad undersøger man, når man ser på det sociale miljø i en tekst?","o":["Personernes økonomi og plads i samfundet","Vejret og årstiden i hele fortællingen","Hvor mange sider hele teksten fylder","Hvilke rim digteren anvender i teksten"],"a":"Personernes økonomi og plads i samfundet","r":"Det sociale miljø handler om klasse, økonomi og relationer. Det fysiske miljø er steder og ting."},
{"l":8535,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør Sofie, hvis hun 'pådutter' sin bror en holdning?","o":["hun overbeviser ham om noget med gode saglige grunde","hun påstår, at han mener noget, som han ikke mener","hun spørger ham, hvad han egentlig selv mener om sagen","hun fortæller andre, hvad han har sagt til hende"],"a":"hun påstår, at han mener noget, som han ikke mener","r":"At pådutte nogen noget er at tillægge dem en mening eller egenskab, de ikke har. Det sker tit, når en debat bliver usaglig."},
{"l":8558,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at et princip bliver 'knæsat'?","o":["at det bliver skrevet ned til arkivet","at det bliver ophævet ved en dom","at det bliver fastslået som gældende","at det bliver bøjet til formålet"],"a":"at det bliver fastslået som gældende","r":"At knæsætte er at slå noget fast som grundregel. Oprindelig satte man et barn på knæet som tegn på, at man anerkendte det."},
{"l":8582,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Han er en rigtig ___: Han retter selv de mindste kommafejl i sine venners beskeder.'","o":["pessimist","patriot","pioner","pedant"],"a":"pedant","r":"En pedant går overdrevent op i små regler og detaljer. En pessimist ser derimod det værste i enhver situation."},
{"l":8607,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken forfatter skrev romanen 'Hærværk' fra 1930?","o":["Tom Kristensen","Henrik Pontoppidan","Herman Bang","Jeppe Aakjær"],"a":"Tom Kristensen","r":"Tom Kristensen skrev 'Hærværk', som regnes for en af de store danske romaner fra tiden mellem de to verdenskrige."},
{"l":8632,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket udsagn om kolon er rigtigt?","o":["Kolon afslutter altid et spørgsmål i teksten","Kolon varsler, at noget forklarende følger","Kolon står kun foran tal og årstal i teksten","Kolon skiller kun to ledsætninger fra hinanden"],"a":"Kolon varsler, at noget forklarende følger","r":"Kolon peger fremad mod en forklaring, en opremsning eller et citat."},
{"l":8655,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Hun bestod prøven, og det gjorde hendes bror ___.'","o":["ligeleders","liggeledes","ligeledes","ligelædes"],"a":"ligeledes","r":"Ordet betyder 'på samme måde' og består af 'lige' og 'ledes'."},
{"l":8673,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kendetegner ekspressionisme i litteraturen?","o":["Nøgterne beskrivelser af den ydre virkelighed","Fine gengivelser af små, flygtige sanseindtryk","Rimede hyldester til den danske sommer og natur","Stærke følelser udtrykt i voldsomme billeder"],"a":"Stærke følelser udtrykt i voldsomme billeder","r":"Ekspressionismen vil udtrykke det indre. Virkeligheden forvrænges for at vise stærke følelser."},
{"l":8695,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Alle elsker tanken om en stille landsby, ikke mindst dem, der ikke bor der.' Hvad antydes?","o":["At idealet holder bedst på afstand","At landsbyer er blevet alt for dyre","At landsbyer bør have mere trafik","At alle snart flytter ud på landet"],"a":"At idealet holder bedst på afstand","r":"Den sidste del vender ros til spot: Det er fortrinsvis folk uden for landsbyen, der holder af ideen."},
{"l":8717,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad er bekendelseslitteratur, der fik stor plads i dansk litteratur i 1970'erne?","o":["Tekster, hvor en præst forklarer, hvad man må og ikke må","Tekster, hvor forfatteren åbent skriver om sit eget liv","Tekster, hvor en journalist afslører en kendt politiker","Tekster, hvor en detektiv får forbryderen til at tilstå"],"a":"Tekster, hvor forfatteren åbent skriver om sit eget liv","r":"I bekendelseslitteraturen fortæller forfatteren om personlige og ofte svære erfaringer, gerne set fra kvinders side."},
{"l":8739,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'De sad i bilen. Hun drak af sin kaffe. Han tændte radioen og slukkede den igen. Det regner, sagde hun.' Hvad er det læseren især mærker?","o":["At de er glade og ser frem til ferien","At de er meget optagede af vejret og vejrudsigten","At der er noget usagt og anspændt imellem dem","At de netop har mødt hinanden for første gang"],"a":"At der er noget usagt og anspændt imellem dem","r":"Der sker kun små ting, og de taler om vejret. Netop det, der ikke bliver sagt, skaber spændingen."},
{"l":8760,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find det rigtige ord: 'Journalisten lavede et ___ med forfatteren.'","o":["intervju","interviev","intervew","interview"],"a":"interview","r":"Ordet er lånt fra engelsk og beholder sin stavemåde med -view."},
{"l":8778,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Gamle huse holder bedre end nye, siger mange og peger på de flotte bindingsværkshuse i byens gamle kvarter. Men de huse, der blev dårligt bygget for 300 år siden, står der ikke længere.' Hvilken fejl vil skribenten afsløre?","o":["Man ser kun dem, der har overlevet, og ikke de andre","Man bruger forkerte ord om, hvordan husene er bygget","Man overser, at nye huse er dyrere end de gamle","Man sammenligner træhuse med huse af mursten"],"a":"Man ser kun dem, der har overlevet, og ikke de andre","r":"De svage huse er væk og kan ikke tælle med. Derfor er sammenligningen skæv, for kun de bedste gamle huse er tilbage."},
{"l":8800,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er et 'dogme'?","o":["en gammel fortælling om guder og helte","en læresætning, der ikke må betvivles","en overdreven ros af en stærk leder","en hemmelig aftale mellem to lande"],"a":"en læresætning, der ikke må betvivles","r":"Et dogme er en fast grundsætning, man skal acceptere uden diskussion. Derfor kaldes en stivnet person dogmatisk."},
{"l":8820,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Vi så filmen og havde en ___ diskussion i klassen.'","o":["efterfølgene","efterfølende","efterfølgende","efterføljende"],"a":"efterfølgende","r":"Ordet er dannet af 'efterfølge' med -ende, så både g og d skal med."},
{"l":8839,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Ord som 'chauffør', 'restaurant' og 'garage' er lånt fra det samme sprog. Hvilket?","o":["tysk","græsk","italiensk","fransk"],"a":"fransk","r":"Alle tre ord kommer fra fransk. Man kan stadig høre det, for udtalen minder om den franske, f.eks. sj-lyden i 'garage'."},
{"l":8862,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Vi byggede en mur af høflighed, / sten for sten, goddag for goddag, / og nu kan ingen af os se over den.' Hvad siger digtet?","o":["Høflighed kan skabe afstand mellem mennesker","Mennesker kan med tiden blive for høflige","Muren er bygget for at skille to haver ad","Høflighed er nødvendigt for at leve tæt sammen"],"a":"Høflighed kan skabe afstand mellem mennesker","r":"Hver hilsen er en sten, og muren skiller dem til sidst. Det pæne er blevet det, der holder dem væk fra hinanden."},
{"l":8882,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Læsetimer gør helt sikkert eleverne bedre til at stave.' Hvad er styrkemarkøren?","o":["læsetimer","helt sikkert","eleverne","at stave"],"a":"helt sikkert","r":"En styrkemarkør viser, hvor sikker afsenderen er på sin påstand. Her er sikkerheden meget stor."},
{"l":8904,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Den bog er den bedste, fordi ingen anden bog er lige så god.' Hvilken argumentationsfejl er det?","o":["personangreb","falsk dilemma","cirkelslutning","forhastet generalisering"],"a":"cirkelslutning","r":"Begrundelsen siger det samme som påstanden. Argumentet går i ring og beviser derfor ingenting."},
{"l":8921,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Antallet af cykeluheld pr. 1.000 cyklister i Holmby er faldet med 20 procent, mens det samlede antal cykeluheld er steget.' Hvordan kan begge dele være sandt?","o":["Uheldene er blevet alvorligere end tidligere","Cyklisterne er begyndt at køre med hjelm","Der er færre uheld med biler end med cykler","Der er kommet mange flere cyklister i byen"],"a":"Der er kommet mange flere cyklister i byen","r":"Risikoen pr. cyklist er faldet, men flere cyklister kan alligevel give flere uheld. Det er forskellen mellem antal og andel."},
{"l":8942,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kaldes i matematik en grundsætning, som man godtager uden bevis, og som andre sætninger bygger på?","o":["aksiom","teorem","parameter","variabel"],"a":"aksiom","r":"Et aksiom er et udgangspunkt, der ikke bevises. Et teorem er det modsatte: en sætning, der netop er bevist."},
{"l":8960,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Ordet 'motel' er dannet af 'motor' og 'hotel'. Hvad kaldes sådan et ord?","o":["initialord","teleskopord","afledning","arveord"],"a":"teleskopord","r":"Et teleskopord skubber dele af to ord sammen til ét, ligesom et teleskop trækkes sammen. 'Brunch' af 'breakfast' og 'lunch' er et andet eksempel."},
{"l":8982,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket af disse sprog, som alle tales i Norden, hører ikke til de germanske sprog?","o":["færøsk","islandsk","grønlandsk","norsk"],"a":"grønlandsk","r":"Grønlandsk tilhører den eskimo-aleutiske sprogfamilie og er ikke i familie med dansk. Færøsk, islandsk og norsk er nordgermanske."},
{"l":9003,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad betyder det retoriske begreb kairos?","o":["Den sidste del af en lang tale","Afsenderens gode personlige ry","Den kritik, der kommer bagefter","Det rette tidspunkt at sige noget på"],"a":"Det rette tidspunkt at sige noget på","r":"Kairos handler om at ramme det rigtige øjeblik. Det samme argument kan virke stærkt den ene dag og falde til jorden den anden."},
{"l":9025,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Firmaet har fine ordrer, men dårlig 'likviditet'. Hvad mangler det?","o":["penge til rådighed lige nu","dygtige folk i ledelsen","varer på lageret","kunder i udlandet"],"a":"penge til rådighed lige nu","r":"Likvide midler er penge, der flyder frit og kan bruges med det samme. Et firma kan altså tjene godt og alligevel mangle kontanter."},
{"l":9047,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En person blev dømt 'in absentia'. Hvad betyder det?","o":["med en særlig mild straf","uden at være til stede i retten","efter at have tilstået det hele","af en dommer fra et andet land"],"a":"uden at være til stede i retten","r":"Latin 'absentia' betyder fravær. Ordet 'absent' er i familie med det."},
{"l":9064,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'I vores familie fortæller vi tit om dengang, far reddede en hund fra isen. Hver gang er isen lidt tyndere og hunden lidt mindre. Far er selv begyndt at tro på den tynde is.' Hvad viser sidste sætning?","o":["At far aldrig selv var til stede ved søen den dag","At isen på søen faktisk er blevet tyndere med årene","At en gentaget fortælling kan ændre selve erindringen","At hunden stadig bor hos familien den dag i dag"],"a":"At en gentaget fortælling kan ændre selve erindringen","r":"Historien vokser for hver gang, og til sidst er selv hovedpersonen ikke sikker. Det handler om hukommelsens natur."},
{"l":9085,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er et 'columbusæg'?","o":["en sjælden fugl fra det amerikanske kontinent","en dyr gave fra en fjern og fremmed egn","en plan, som ingen anden har turdet prøve","en enkel løsning, der virker indlysende bagefter"],"a":"en enkel løsning, der virker indlysende bagefter","r":"Ifølge en historie fik Columbus et æg til at stå ved at trykke enden flad. Alle kunne gøre det, da de havde set det."},
{"l":9103,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Ved lukkelyde spærres luftstrømmen et øjeblik helt. Hvilken gruppe består kun af lukkelyde?","o":["p, t og k","f, s og h","m, n og ng","l, r og j"],"a":"p, t og k","r":"Ved p, t og k spærres luften helt og slippes så fri. Ved f og s siver luften ud hele tiden, og ved m og n går den ud gennem næsen."},
{"l":9123,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Vi bør tilbyde alle elever latin, for det styrker logikken. Elever, der selv har valgt latin, klarer sig nemlig bedre i de andre fag.' Hvad er svagheden i belægget?","o":["Latin er ikke længere noget levende sprog i Europa","Det kan være de dygtigste, der vælger latin","Der findes ikke nok lærere, der kan latin","Logik kan også læres i matematikfaget"],"a":"Det kan være de dygtigste, der vælger latin","r":"Hvis særligt dygtige vælger faget, er det ikke faget, der gør dem dygtige. Årsagen kan gå modsat af det påståede."},
{"l":9147,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Kun én af disse sætninger har et udsagnsord med -s i passiv. Hvilken?","o":["Vi ses igen senest på fredag.","Det lykkes nok senest på fredag.","Opgaverne afleveres senest på fredag.","Hun mindes altid sin barndom."],"a":"Opgaverne afleveres senest på fredag.","r":"Passiv kan omskrives med 'bliver': 'Opgaverne bliver afleveret'. 'Ses' betyder her at se hinanden, og 'lykkes' og 'mindes' har aktiv betydning, selvom de ender på -s."},
{"l":9167,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kendetegner en 'polemik'?","o":["en nøgtern, neutral redegørelse","en kærlig tale ved en fest","en kort, rimet fortælling","en skarp, offentlig ordstrid"],"a":"en skarp, offentlig ordstrid","r":"Ordet kommer af græsk 'polemos', krig. I en polemik angriber man modpartens synspunkter med skarpe ord."},
{"l":9183,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Efter festen fandt jeg Mikkels jakke i garderoben. Jeg tog den med hjem. Det var jo bare for at give den til ham. Der gik tre uger. Den hang godt på min stol.' Hvad vil teksten have læseren til at forstå?","o":["Fortælleren har en anden grund end den, der nævnes","Fortælleren har helt glemt, hvem jakken tilhører","Fortælleren vil sælge Mikkels jakke videre","Fortælleren har vasket jakken for Mikkel"],"a":"Fortælleren har en anden grund end den, der nævnes","r":"'Jo bare' lyder som en bortforklaring, og tre uger på stolen modsiger den. Her er følelser på spil, der ikke siges."},
{"l":9205,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder forleddet 'eu-' i ordene 'eufori' og 'eufoni'?","o":["dobbelt eller to gange","god eller behagelig","hurtig eller let","mørk eller natlig"],"a":"god eller behagelig","r":"Eufoni er en behagelig klang, og eufori er en stærk følelse af velvære. Det modsatte led er dys-, der betyder dårlig."},
{"l":9225,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Sæt ind: 'I parken stod en lille ___, hvor orkesteret spillede om søndagen.'","o":["pavilon","pavilion","pavillon","pavvillon"],"a":"pavillon","r":"Ordet kommer fra fransk og har dobbelt-l. Der er ikke noget i efter l'erne."},
{"l":9245,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Fruen smilede. Hun løftede koppen og satte den ned igen. Der var stille et øjeblik. – Er det ikke snart forår? sagde hun og så ud ad vinduet.' Hvordan aner vi fruens følelser?","o":["Fortælleren siger direkte, hvad hun føler","Fruen forklarer alle sine tanker højt","Teksten giver et langt tilbageblik","Gennem små handlinger og en løs replik"],"a":"Gennem små handlinger og en løs replik","r":"Koppen, stilheden og blikket ud ad vinduet antyder en uro. Læseren må selv tyde det, som i impressionismen."},
{"l":9266,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Dejligt at se dig! sagde Peter til sin nabo og holdt døren. Han havde kun inviteret hende, fordi hun ejede den stige, han ville låne.' Hvilket misforhold beskrives?","o":["Mellem hans venlige ord og hans beregnende hensigt","Mellem naboens alder og længden på hendes stige","Mellem antallet af gæster og pladserne ved bordet","Mellem hans gamle hus og hendes nye dør ud til gaden"],"a":"Mellem hans venlige ord og hans beregnende hensigt","r":"Hans hilsen lyder varm, men fortælleren afslører et skjult motiv. Det er kontrasten mellem ydre og indre, der er pointen."},
{"l":9287,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Et byrådsmedlem er 'inhabil' i en sag om sin brors byggetilladelse. Hvad betyder det?","o":["Medlemmet mangler den uddannelse, som en sag af den slags kræver","Medlemmet er for tæt knyttet til sagen til at afgøre den","Medlemmet er for sygt til at deltage i mødet","Medlemmet har mistet sin stemmeret i kommunen"],"a":"Medlemmet er for tæt knyttet til sagen til at afgøre den","r":"Den, der har personlig interesse i en sag, må ikke deltage i afgørelsen. Det handler om upartiskhed, ikke om evner."},
{"l":9308,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket ord indleder den indskudte ledsætning i 'Manden, hvis hund løb væk, ringede til politiet.'?","o":["Manden","væk","hvis","ringede"],"a":"hvis","r":"Her er 'hvis' et henførende stedord, der viser, at hunden er mandens. Det indleder ledsætningen mellem de to kommaer."},
{"l":9330,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Flyet rystede kraftigt på grund af ___.'","o":["turbulenz","turpulens","turbulents","turbulens"],"a":"turbulens","r":"Ordet ender på -ens med s og uden t."},
{"l":9347,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Filosoffen John Locke mente, at al viden stammer fra sansernes erfaring. Hvilken retning hører han til?","o":["empirisme","rationalisme","idealisme","stoicisme"],"a":"empirisme","r":"Empirismen er rationalismens modstykke og siger, at viden begynder med det, vi sanser."},
{"l":9370,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Vendingen 'Hav en god dag' er efterlignet fra engelsk. Hvad kaldes sådan et sprogligt lån?","o":["gallicisme","anglicisme","germanisme","arkaisme"],"a":"anglicisme","r":"Latin 'anglicus' betyder engelsk. En gallicisme er et lån fra fransk, og en germanisme er et lån fra tysk."},
{"l":9389,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Under frikvarteret skifter Hassan fra dansk til arabisk og tilbage igen i samme samtale. Hvad kaldes det?","o":["sociolekt","eufemisme","kodeskift","lånord"],"a":"kodeskift","r":"Kodeskift er, når man veksler mellem to sprog i samme samtale. Det er almindeligt blandt mennesker, der taler flere sprog."},
{"l":9411,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket led står i forfeltet i: 'Aldrig har jeg set så mange stjerner.'","o":["grundled","genstandsled","udsagnsled","sætningsadverbial"],"a":"sætningsadverbial","r":"'Aldrig' er et sætningsadverbial, der normalt står efter grundleddet. Her er det flyttet frem i forfeltet, hvilket giver det ekstra vægt."},
{"l":9435,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Et farligt ___ skal opbevares i en lukket beholder.'","o":["kemikalie","kemikallie","kemikali","chemikalie"],"a":"kemikalie","r":"Ordet skrives med k, ét l og ender på -ie."},
{"l":9455,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad kaldes det, når 'skyskraber' er dannet ved at oversætte engelsk 'skyscraper' led for led?","o":["arveord","oversættelseslån","teleskopord","afkortning"],"a":"oversættelseslån","r":"Ved et oversættelseslån låner man ordets opbygning, men bruger egne ord. 'Skyskraber' ligner derfor ikke det engelske ord på overfladen."},
{"l":9476,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvordan er en klassisk sonet delt op?","o":["Tre strofer med seks vers og en med ét vers","Fire strofer med to vers og én med seks vers","To strofer med fire vers og to med tre vers","Syv strofer med to vers og ingen rim i dem"],"a":"To strofer med fire vers og to med tre vers","r":"Den klassiske sonet har 14 vers fordelt med fire, fire, tre og tre. Ofte kommer der en vending efter de første otte."},
{"l":9495,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'Veje, broer og jernbaner er en del af landets ___.'","o":["infrastrukter","infastruktur","infrasstruktur","infrastruktur"],"a":"infrastruktur","r":"Ordet består af 'infra' og 'struktur'. Husk r'et i 'infra' og -ur til sidst."},
{"l":9516,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket af ordene skal altid skrives med stort, når det står midt i en sætning?","o":["storebælt","bornholmer","københavner","jyde"],"a":"storebælt","r":"Storebælt er navnet på et farvand. Ord for indbyggere skrives med lille."},
{"l":9540,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Hvornår har I sidst set en tilskuer rejse sig og klappe af en tabel? Vi spiller ikke for at se pæne ud i statistikken. Vi spiller, fordi nogen står og fryser på lægterne i november og alligevel kommer igen.' Hvad bruger taleren det indledende spørgsmål til?","o":["At få tilhørerne til at svare på, hvor ofte de går til kamp","At gøre tanken om, at tallene er det vigtigste, til grin","At kritisere tilskuerne for ikke at følge med i klubbens resultater","At vise, at klubben mangler overblik over sine egne kampe"],"a":"At gøre tanken om, at tallene er det vigtigste, til grin","r":"Spørgsmålet er retorisk og tegner et komisk billede, som ingen kan nikke til. Det ligner en bebrejdelse af tilskuerne, men talen hylder dem tværtimod."},
{"l":9557,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En virksomhed er 'insolvent'. Hvad betyder det?","o":["Den har åbnet en ny afdeling","Den ejes af sine ansatte","Den kan ikke betale sin gæld","Den er registreret i udlandet"],"a":"Den kan ikke betale sin gæld","r":"Solvens er evnen til at betale, og in- betyder ikke. Insolvens kan føre til konkurs."},
{"l":9576,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Der var en tid, hvor vi talte om fremtiden, som var den et sted, man kunne rejse til. Nu taler vi mest om vejret.' Hvad fortæller kontrasten om forholdet?","o":["At de to er flyttet til et sted med dårligere vejr","At de snart skal ud at rejse til et bestemt land","At de har fået mere at tale om end før i tiden","At noget levende og håbefuldt er sivet ud af det"],"a":"At noget levende og håbefuldt er sivet ud af det","r":"Samtaler om vejret er det, man taler om, når der ikke er andet. Sammenligningen med fremtidsdrømmene viser tabet."},
{"l":9598,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket led er ledsætningen i: 'At Amina vandt løbet, overraskede alle.'","o":["grundled","genstandsled","hensynsled","omsagnsled"],"a":"grundled","r":"Spørg 'Hvad overraskede alle?' Svaret er hele ledsætningen, så den er sætningens grundled."},
{"l":9619,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Der er koldt herinde, sagde fru Holm og så på det åbne vindue.' Hvad gør hun med replikken?","o":["Hun giver en vejrudsigt til dem, der er ude","Hun beder indirekte om at få vinduet lukket","Hun roser dem, der har luftet ud i rummet","Hun fortæller, at hun skal hente sin jakke"],"a":"Hun beder indirekte om at få vinduet lukket","r":"Sætningen er formet som en konstatering, men er i virkeligheden en opfordring. Det kaldes en indirekte sproghandling."},
{"l":9641,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad undersøger man ved en biografisk læsning?","o":["Hvor mange bøger forfatteren i alt har skrevet","Hvordan teksten er bygget op uden nogen baggrund","Sammenhængen mellem forfatterens liv og teksten","Hvad læsere i dag betaler for at købe bogen"],"a":"Sammenhængen mellem forfatterens liv og teksten","r":"En biografisk læsning bruger viden om forfatterens liv til at forstå værket. Man skal dog huske, at digtning ikke er det samme som dagbog."},
{"l":9662,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Avisen kalder hende en 'koryfæ' inden for dansk havforskning. Hvad er hun?","o":["en lovende, men ukendt begynder","en kritiker uden for faget","en assistent på laboratoriet","en førende og anerkendt skikkelse"],"a":"en førende og anerkendt skikkelse","r":"Koryfæ var lederen af koret i det græske teater. I dag er det en person, der står øverst i sit fag."},
{"l":9683,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Hvis en regel kun følges, når nogen kigger, er det så reglen, man respekterer, eller kameraet?' Hvad får spørgsmålet læseren til at overveje?","o":["Forskellen mellem ydre kontrol og indre overbevisning","Forskellen mellem gamle og nye typer overvågningskameraer","Forskellen mellem regler i skolen og regler i hjemmet","Forskellen mellem hvad der er lovligt og hvad der er dyrt"],"a":"Forskellen mellem ydre kontrol og indre overbevisning","r":"Spørgsmålet skelner mellem at adlyde af frygt og at gøre noget, fordi man er enig. Det handler om moral, ikke teknik."},
{"l":9700,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad vil det sige at være 'mellem Scylla og Charybdis'?","o":["at have to gode tilbud på én gang","at stå mellem to lige farlige valg","at være på vej hjem efter en lang rejse","at skulle tale to fremmede sprog"],"a":"at stå mellem to lige farlige valg","r":"I 'Odysseen' skal Odysseus sejle gennem et stræde mellem to uhyrer. Vælger man at undgå det ene, nærmer man sig det andet."},
{"l":9722,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad vil det sige at 'sætte sit lys under en skæppe'?","o":["at spare på strømmen i sit eget hjem","at gemme sine penge for alle andre","at skjule sine evner af overdreven beskedenhed","at arbejde sent om aftenen uden at blive set"],"a":"at skjule sine evner af overdreven beskedenhed","r":"En skæppe var et mål til korn. Sætter man den over et lys, kan ingen se, hvad man kan."},
{"l":9742,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Yoghurt A er uden kunstigt sødemiddel, men har jordbæraroma fremstillet på en fabrik. Yoghurt B er lavet af rigtige jordbær, men er sødet med kunstigt sødemiddel. På begge bægre står der med store bogstaver: Naturlig smag.' Hvad kan man slutte om ordet 'naturlig'?","o":["Det passer kun på den af yoghurterne, der har rigtige bær","Det fortæller, at begge yoghurter er lige sunde at spise","Det er et krav, der skal stå på alle bægre med jordbær","Det bruges som et rosende stempel uden en fast betydning"],"a":"Det bruges som et rosende stempel uden en fast betydning","r":"To yoghurter med hver sin kunstige ingrediens bruger samme ord, så ordet siger mest noget om salg. Yoghurt B har rigtige bær, men den har også et kunstigt sødemiddel, så ordet passer ikke bedre dér."},
{"l":9763,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket engelsk ord er lånt fra nordisk i vikingetiden?","o":["window","table","chair","music"],"a":"window","r":"'Window' kommer af det nordiske 'vindauga', et 'vindøje'. De tre andre ord har engelsk fået sydfra, gennem latin og fransk."},
{"l":9784,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilket digt af T.S. Eliot fra 1922 fik stor betydning for modernismen?","o":["Det tabte Paradis","Det øde land","Odysseen","Beowulf"],"a":"Det øde land","r":"Eliots 'The Waste Land', på dansk 'Det øde land', består af brudstykker af stemmer og citater, og det påvirkede mange modernister."},
{"l":9805,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilken gren af filosofien stiller spørgsmålet 'Hvad vil det sige, at noget er til?'","o":["etik","æstetik","ontologi","logik"],"a":"ontologi","r":"Græsk 'on' betyder det værende. Ontologien er læren om det, der er, og om værens natur."},
{"l":9827,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Et rødt trafiklys, en smiley og et ord står alle for noget andet end sig selv. Hvilket fag studerer sådanne tegn?","o":["statik","akustik","kinetik","semiotik"],"a":"semiotik","r":"Græsk 'semeion' betyder tegn. Semiotikken undersøger alle former for tegn, ikke kun sproglige."},
{"l":9849,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Den, der ikke kender sin historie, er dømt til at gentage den, siger man. Min erfaring er, at de, der kender den, også gentager den, nu blot med bedre argumenter.' Hvad tilføjer skribenten til det kendte ord?","o":["En skepsis over for, om viden i sig selv forhindrer fejl","En opfordring til, at historie skal fylde mere i skolen","En advarsel om, at historiebøgerne ikke er rigtige","En glæde over, at folk bliver bedre til at argumentere"],"a":"En skepsis over for, om viden i sig selv forhindrer fejl","r":"Skribenten vender talemåden: At kende fortiden er ingen garanti. Viden kan endda bruges til at retfærdiggøre det samme igen."},
{"l":9872,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kendetegner fortælleformen i folkeviser?","o":["Lange beskrivelser af personernes følelsesliv","Springende handling med gentagelser og omkvæd","Stram argumentation med tal og kilder","Fri vers uden rytme og uden strofer"],"a":"Springende handling med gentagelser og omkvæd","r":"Folkevisen springer fra scene til scene og bruger faste vendinger. Formen hænger sammen med, at den blev sunget og husket."},
{"l":9887,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Karl Popper mente, at en videnskabelig teori skal kunne 'falsificeres'. Hvad betyder det?","o":["Man skal kunne bevise den endegyldigt med ét forsøg","Man skal kunne forfalske dens resultater uden at blive opdaget","Man skal kunne vise, at den er forkert, hvis den er det","Man skal kunne forklare den for almindelige mennesker"],"a":"Man skal kunne vise, at den er forkert, hvis den er det","r":"Hos Popper er det netop muligheden for at blive modbevist, der gør en teori videnskabelig."},
{"l":9909,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Forskere viser, at læsning på skærm ofte er mere overfladisk end læsning på papir. Men forsøgene er mest lavet med voksne, som er vokset op med papir. Det er derfor uklart, hvad resultaterne siger om nutidens børn.' Hvad er det uklare?","o":["Om voksne i dag er blevet dygtigere til at læse end nutidens børn","Om papir faktisk bliver brugt til at læse på i skolerne","Om skærme er mere overfladiske end voksne, der læser dem","Om resultatet skyldes selve skærmen eller vaner fra barndommen"],"a":"Om resultatet skyldes selve skærmen eller vaner fra barndommen","r":"Hvis deltagerne er præget af papirvaner, kan forskellen handle om træning og ikke om mediet. Teksten skelner mellem resultat og fortolkning."},
{"l":9930,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad kaldes perioden i Europa efter middelalderen, hvor kunst og videnskab blomstrede?","o":["renæssance","renæsance","renessance","renæssanse"],"a":"renæssance","r":"Ordet er fransk for 'genfødsel'. Det har æ, dobbelt-s og -ance med c."},
{"l":9949,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken versefod består af en ubetonet stavelse efterfulgt af en betonet?","o":["trokæ","jambe","daktyl","anapæst"],"a":"jambe","r":"I en jambe går rytmen svag-stærk. Det omvendte, stærk-svag, kaldes trokæ."},
{"l":9971,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad er et prosadigt?","o":["En roman, der er skrevet i rimede vers fra ende til anden","Et digt, der er oversat fra fransk til dansk prosa","En tekst uden verslinjer, men med digtets billedsprog","En kort nyhed, der er sat op i tre korte verslinjer"],"a":"En tekst uden verslinjer, men med digtets billedsprog","r":"Et prosadigt ligner prosa på siden, men har digtets tætte sprog og billeder."},
{"l":9992,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Tolerance er en dyd, lærer vi. Men tolerance forudsætter, at der er noget, man ikke bryder sig om; det, man holder af, behøver man ikke tolerere. Den, der siger, at hun tolererer sine naboer, fortæller altså også, hvad hun synes om dem.' Hvad er skribentens pointe?","o":["At tolerance er en lige så stor dyd som kærlighed","At man bør tale mere med sine naboer, end man gør","At naboer er sværere at holde af end andre mennesker","At ordet tolerance rummer en skjult afstandtagen"],"a":"At ordet tolerance rummer en skjult afstandtagen","r":"Man tolererer kun det, man ikke kan lide. Ordet lyder pænt, men fortæller samtidig, at man tager afstand."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
